  "Perinephric fluid collection with enhancing wall and internal gas, consistent with renal abscess.",
  "Wedge-shaped cortical defect with loss of enhancement, consistent with segmental renal infarct.",
  "Hyperdense lesion with no enhancement, consistent with calcified renal papilla (nephrocalcinosis).",
  "Diffuse cortical thinning and bilateral small kidneys, typical of chronic kidney disease.",
