  "Linear mucosal break at the posterior midline with surrounding edema (Anal Fissure).",
  "Inflamed, bulging area with purulent exudate near dentate line (Anorectal Abscess).",
  "Ulceroproliferative lesion with friability and central necrosis (Anal SCC).",
  "Exophytic, wart-like growths with papilliform projections (Condyloma Acuminata).",
  "Large, deep ulcerations with irregular margins (CMV Colitis).",
  "Transverse ulcers with undermined edges and nodularity (Tuberculous Colitis).",
  "Flask-shaped ulcers with heaped margins and intervening normal mucosa (Amebic Colitis).",
